object Main {
  def jumlah(L: List[Int]): Int = {
    L match {
      case Nil => 0
      case head :: tail => head + jumlah(tail)
    }
  }

  def main(args: Array[String]): Unit = {
    val nums = List(1, 2, 3, 4, 5)
    println(jumlah(nums))
    println(nums.reduce(_ + _))
  }
}

object Main {
  def search1(L: List[Int], q: Int): Int = {
    L.count(_ == q)
  }

  def search2(L: List[Int], q: Int): Int = {
    L match {
      case Nil => 0
      case head :: tail =>
        if (head == q) 1 + search2(tail, q) else search2(tail, q)
    }
  }

  def main(args: Array[String]): Unit = {
    val data = List(1, 2, 3, 1, 4, 3)
    println(search1(data, 1))
    println(search2(data, 1))
  }
}

object Main {
  def sumGenap1(L: List[Int]): Int = {
    L.filter(_ % 2 == 0).reduce(_ + _)
  }

  def sumGenap2(L: List[Int]): Int = {
    L match {
      case Nil => 0
      case head :: tail =>
        if (head % 2 == 0) head + sumGenap2(tail)
        else sumGenap2(tail)
    }
  }

  def main(args: Array[String]): Unit = {
    val nums = List(1, 2, 3, 4)
    println(sumGenap1(nums))
    println(sumGenap2(nums))
  }
}
